// arb_if.sv: the arbiter's pins, with one clocking block for the driver and
// one for the monitor. Complete: you do not edit this file.
//
// drv_cb drives req with the default output skew #0: the value lands just after
//   the clock edge (1800-2023 14.3, 14.16), so the DUT sees it from then until
//   the next edge.
// mon_cb samples with the default input skew #1step: the values just before the
//   edge (14.4, 14.13). Those are the req and gnt the DUT's pointer used at that
//   edge, so one sample is one arbitration decision.
interface arb_if #(parameter int N = 4) (input logic clk);
  timeunit 1ns; timeprecision 1ps;

  logic         rst_n;
  logic [N-1:0] req = '0;            // no request until the driver drives one
  logic [N-1:0] gnt;

  clocking drv_cb @(posedge clk);
    input  rst_n;
    output req;
  endclocking

  clocking mon_cb @(posedge clk);
    input rst_n, req, gnt;
  endclocking
endinterface
